		  8 * aarch64_insn_decode_immediate(AARCH64_INSN_IMM_12,
						    le32_to_cpup(tramp + 8));

	ret = aarch64_insn_write_literal_u64((void *)literal, (u64)func);
	WARN_ON_ONCE(ret);
